last_time = CASE
WHEN id = #{item.id} THEN #{item.lastTime}
ELSE last_time END,
next_time = CASE
WHEN id = #{item.id} THEN #{item.nextTime}
ELSE next_time END,
execution_count = CASE
WHEN id = #{item.id} THEN #{item.executionCount}
ELSE execution_count END,
update_time = CASE
WHEN id = #{item.id} THEN #{item.updateTime}
ELSE update_time END WHERE id IN
