SELECT COUNT(DISTINCT t1.id)
FROM
daily_plan t1
INNER JOIN daily_plan_target_relation t2 on t1.id = t2.plan_id


        AND t2.target_id = #{targetId}


        AND t1.daily_type = #{dailyType}


        and t1.create_time >= #{period.begin}


        and t1.create_time <= #{period.end}
